#include "station/ModularStationAssemblySystem.h"
#include <set>
namespace subspace {
bool ModularStationAssemblySystem::Connect(ModularStationPlan&p,std::uint64_t a,const std::string&sa,std::uint64_t b,const std::string&sb) const {if(a==b||a==0||b==0)return false;auto findNode=[&](std::uint64_t id)->ModularStationNode*{for(auto&n:p.modules)if(n.id==id)return &n;return nullptr;};auto*A=findNode(a);auto*B=findNode(b);if(!A||!B)return false;StationSocket*as=nullptr,*bs=nullptr;for(auto&s:A->sockets)if(s.id==sa)as=&s;for(auto&s:B->sockets)if(s.id==sb)bs=&s;if(!as||!bs||as->occupied||bs->occupied||as->type!=bs->type)return false;as->occupied=bs->occupied=true;p.connections.push_back({a,b,sa,sb});return true;}
ModularStationValidation ModularStationAssemblySystem::Validate(const ModularStationPlan&p) const {ModularStationValidation v;std::set<std::uint64_t> ids;for(const auto&m:p.modules){if(m.id==0||!ids.insert(m.id).second)v.errors.push_back("duplicate/invalid module id");v.netPower+=m.powerGeneration-m.powerUse;v.storage+=m.storage;if(m.function==StationModuleFunction::Dock)++v.docks;}if(p.modules.empty())v.errors.push_back("station has no modules");if(v.netPower<0)v.errors.push_back("station power deficit");if(v.docks==0)v.errors.push_back("station has no dock");if(p.modules.size()>1&&p.connections.size()+1<p.modules.size())v.errors.push_back("station graph is disconnected");v.valid=v.errors.empty();return v;}
} // namespace subspace
